def checked_parse_int(s: str, default: int = 0) -> int:
    """Safely convert a string to an integer, returning a default value if the conversion fails."""
    try:
        return int(s)
    except ValueError:
        return default

def parse_percentage(s: str) -> float:
    """Parse a string as a percentage value."""
    return checked_parse_int(s.strip('%')) / 100

def parse_conditional(spec: str) -> int:
    """Parse a conditional 'mm' spec of the form 'x<y'."""
    x, _, y = spec.partition('<')
    x = checked_parse_int(x)
    y = checked_parse_int(y)
    return min(x, y)

